const result = $input.item.json.result || $input.item.json;
const config = result.config || {};

// Extract text - handle objects by stringifying them nicely
function getText(field) {
  if (!field) return 'Not specified';
  if (typeof field === 'string') return field;
  if (typeof field === 'object') {
    // If object has a 'text' property, use it
    if (field.text) return field.text;
    // Otherwise, format the object nicely
    return JSON.stringify(field, null, 2);
  }
  return String(field);
}

const promptText = `You are a Cursor cloud agent named ${result.agent_name || 'Agent'}.

Your responsibilities include:
${getText(config.responsibilities)}

Constraints:
${getText(config.constraints)}

Success Criteria:
${getText(config.success_criteria)}

Please respond briefly and clearly.`;

return [{
  json: {
    api_key: result.api_key,
    agent_instance_id: result.agent_instance_id,
    request_body: JSON.stringify({
      model: "gpt-4.1",
      prompt: { text: promptText }
    })
  }
}];

// Get the input - handle the nested structure from Postgres query
const input = $input.item.json;

// Extract documents array from result.documents
const documents = input.result?.documents || input.documents || [];

// Get agent response from Set node
const agentResponseNode = $('Store Agent Response');
const agentResponse = agentResponseNode?.item?.json?.agent_response || {};

// Process each document (if multiple) or single document
const processedDocuments = documents.map(document => {
  // Extract document content - prioritize raw_text_content
  const documentContent = document.raw_text_content || 
                          (document.file_content ? 
                            Buffer.from(document.file_content, 'base64').toString('utf8') : 
                            '') ||
                          document.content ||
                          '';

  // Build the complete HTTP request body as an object
  const requestBody = {
    document: {
      document_id: document.document_id,
      document_name: document.document_name,
      document_type: document.document_type,
      content: documentContent,
      metadata: {
        file_extension: document.file_extension || null,
        file_mime_type: document.file_mime_type || null,
        file_size_bytes: document.file_size_bytes || null,
        version_number: document.version_number || null
      },
      agent_context: {
        agent_id: agentResponse.id || agentResponse.agent_id || null,
        agent_name: agentResponse.name || agentResponse.agent_name || null,
        agent_status: agentResponse.status || agentResponse.agent_status || null
      }
    }
  };

  // Stringify the request body
  const requestBodyString = JSON.stringify(requestBody);

  return {
    json: {
      document_id: document.document_id,
      project_id: document.project_id || input.result?.project_id || input.project_id,
      document_name: document.document_name,
      document_type: document.document_type,
      serialization_payload: requestBody.document,
      request_body_string: requestBodyString,
      request_body: requestBody,
      agent_response: agentResponse,
      raw_content_length: documentContent.length
    }
  };
});

// Return array of documents
return processedDocuments.length > 0 ? processedDocuments : [{
  json: {
    error: "No documents found",
    input_structure: JSON.stringify(input, null, 2)
  }
}];

const apiResponse = $input.item.json;
const documentData = $('Prepare Document for Serialization').item.json;

// Extract serialized data from API response
const serializedData = apiResponse.serialized || 
                      apiResponse.result || 
                      apiResponse.data ||
                      apiResponse;

return [{
  json: {
    document_id: documentData.document_id,
    project_id: documentData.project_id,
    serialized_payload: typeof serializedData === 'object' ? 
                        serializedData : 
                        JSON.parse(serializedData || '{}'),
    api_response: apiResponse
  }
}];

// Get input from Set node that stores agent response
const input = $input.item.json;

// Extract data from Set node
const agentResponse = input.agent_response || {};
const projectId = input.project_id || 1;

// Extract agent response details
const agentId = agentResponse.id || agentResponse.agent_id || null;
const agentStatus = agentResponse.status || agentResponse.agent_status || null;
const agentName = agentResponse.name || agentResponse.agent_name || null;

return [{
  json: {
    project_id: projectId,
    agent_response: agentResponse,
    agent_id: agentId,
    agent_status: agentStatus,
    agent_name: agentName
  }
}];
